    trustGoogleQ1: 'Зачем Google запрашивает эти разрешения?',
    trustGoogleQ1Answer:
      'Доступ к Gmail позволяет Rox читать, отправлять и упорядочивать письма и отправлять их в корзину. Контакты помогают предлагать получателей; настройки почты поддерживают подпись и фильтры. Когда вы подключаете Календарь, его разрешения позволяют Rox показывать календари и создавать или изменять события. Google показывает точные разрешения до одобрения.',
    trustGoogleQ2: 'Получает ли Rox мой пароль Google?',
