    trustMicrosoftQ2: 'Зачем Outlook запрашивает больше разрешений?',
    trustMicrosoftQ2Answer:
      'После входа Rox отдельно запрашивает у Microsoft доступ к Outlook. Доступ к почте позволяет читать, отправлять и упорядочивать письма; контакты помогают предлагать получателей; настройки ящика поддерживают правила и часовой пояс; доступ к календарю позволяет показывать календари и создавать или изменять события. Microsoft показывает точные разрешения до одобрения, а этот шаг можно пропустить и подключиться позже в настройках.',
    trustMicrosoftQ3:
      'Что делать, если в моей организации приложения одобряет только администратор?',
    trustMicrosoftQ3Answer:
      'В некоторых рабочих и учебных аккаунтах приложения может одобрить только администратор. Если из-за этого не работает вход через Microsoft, войдите с помощью почты. Если не работает подключение Outlook, пока пропустите его; аккаунт Rox продолжит работать, а подключиться можно после одобрения администратора.',
    trustSecurityQ1: 'Что значит нулевое хранение данных?',
    trustSecurityQ1Answer:
      'Когда вы пользуетесь агентом, сведения, нужные для запроса, обрабатывает поставщик модели. Наши соглашения с OpenAI и Anthropic предусматривают нулевое хранение данных и запрет обучения на них. Это касается обработки моделями: Rox по-прежнему хранит содержимое рабочего пространства, нужное для работы сервиса.',
    trustSecurityQ2: 'Кто имеет доступ к рабочим данным?',
